/**
 * Leva de temas populares: categorias novas e partes novas das que ja existiam.
 *
 * Mesmo formato de questions.js (pergunta, resposta, aceita, dif, sub), e
 * questions.js junta estas antes de calcular os atalhos de sobrenome — entao
 * elas passam pelas mesmas regras e pelos mesmos testes.
 *
 * Quem disse?: a frase vai no FIM do enunciado, entre aspas duplas, depois da
 * pergunta. A tela separa a citacao e a mostra em destaque (FRASE_NO_FIM, em
 * public/js/app.js). Como ela faz parte do enunciado, chega tambem a quem le a
 * pergunta no leilao e sai palavra por palavra na Pergunta secreta.
 */

const QD = 'Quem disse esta frase?';
